'use client'
import { useEffect, useState } from 'react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
type Parent={_id:string;name:string}; type Vendor={_id:string;name:string;serviceType:string;active:boolean;pickupParentLocationId?:string|null;pickupParent?:{name:string}|null;coverageCount:number;readiness:'ready'|'needs_setup'|'inactive'}; type Destination={parentLocationId:string;name:string;enabled:boolean;serviceFee:number|null}
const services=['shopping','restaurant','printing','indomie']
export default function VendorsPage(){
 const [vendors,setVendors]=useState<Vendor[]>([]),[parents,setParents]=useState<Parent[]>([]),[selected,setSelected]=useState<Vendor|null>(null),[destinations,setDestinations]=useState<Destination[]>([]),[name,setName]=useState(''),[serviceType,setServiceType]=useState('shopping'),[pickup,setPickup]=useState(''),[editPickup,setEditPickup]=useState(''),[duplicateName,setDuplicateName]=useState(''),[duplicateServiceType,setDuplicateServiceType]=useState('shopping'),[saving,setSaving]=useState(false)
 const load=async()=>{const[a,b]=await Promise.all([fetch('/api/admin/vendors',{cache:'no-store'}),fetch('/api/locations',{cache:'no-store'})]),av=await a.json(),pv=await b.json();if(!a.ok)throw new Error(av.error);setVendors(av.vendors);setParents(pv.locations||[])}
 const loadCoverage=async(v:Vendor)=>{setSelected(v);setEditPickup(v.pickupParentLocationId||'');setDuplicateServiceType(v.serviceType);const r=await fetch(`/api/admin/vendors/${v._id}/delivery-rules`,{cache:'no-store'}),p=await r.json();if(!r.ok)return toast.error(p.error);setDestinations(p.destinations)}
 useEffect(()=>{void load().catch(e=>toast.error(e.message))},[])
 async function request(url:string,body:unknown){const r=await fetch(url,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),p=await r.json();if(!r.ok)throw new Error(p.error);return p}
 async function create(){setSaving(true);try{const r=await fetch('/api/admin/vendors',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,serviceType,pickupParentLocationId:pickup||null,active:Boolean(pickup)})}),p=await r.json();if(!r.ok)throw new Error(p.error);setName('');setPickup('');await load();toast.success('Vendor saved.')}catch(e){toast.error(e instanceof Error?e.message:'Unable to create vendor.')}finally{setSaving(false)}}
 async function savePickup(){if(!selected)return;setSaving(true);try{await request(`/api/admin/vendors/${selected._id}`,{pickupParentLocationId:editPickup||null});await load();setSelected(v=>v?{...v,pickupParentLocationId:editPickup,pickupParent:parents.find(p=>p._id===editPickup)?{name:parents.find(p=>p._id===editPickup)!.name}:null}:v);toast.success('Pickup location updated.')}catch(e){toast.error(e instanceof Error?e.message:'Unable to update pickup.')}finally{setSaving(false)}}
 async function setActive(active:boolean){if(!selected)return;setSaving(true);try{await request(`/api/admin/vendors/${selected._id}`,{active});setSelected(v=>v?{...v,active}:v);await load();toast.success(active?'Vendor activated.':'Vendor deactivated.')}catch(e){toast.error(e instanceof Error?e.message:'Unable to update vendor.')}finally{setSaving(false)}}
 async function duplicate(){if(!selected||!duplicateName.trim())return;setSaving(true);try{const r=await fetch(`/api/admin/vendors/${selected._id}/duplicate`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:duplicateName,serviceType:duplicateServiceType})}),p=await r.json();if(!r.ok)throw new Error(p.error);setDuplicateName('');await load();toast.success('Vendor duplicated as inactive.')}catch(e){toast.error(e instanceof Error?e.message:'Unable to duplicate vendor.')}finally{setSaving(false)}}
 async function saveRule(d:Destination){if(!selected)return;try{await request(`/api/admin/vendors/${selected._id}/delivery-rules`,{dropoffParentLocationId:d.parentLocationId,enabled:d.enabled,serviceFee:d.serviceFee});await loadCoverage(selected);await load()}catch(e){toast.error(e instanceof Error?e.message:'Unable to save coverage.')}}
 return <main className="mx-auto max-w-6xl px-4 py-8"><header className="mb-7"><p className="text-sm font-semibold text-violet-700">Operations</p><h1 className="text-3xl font-bold">Fulfillment vendors</h1><p className="mt-2 text-sm text-slate-600">Configure pickup locations and delivery coverage. Customer ordering remains on the legacy flow until Phase 2.</p></header><section className="mb-7 rounded-2xl border bg-white p-5"><h2 className="font-bold">Add vendor</h2><div className="mt-4 grid gap-3 md:grid-cols-4"><input value={name} onChange={e=>setName(e.target.value)} placeholder="Vendor name" className="h-11 rounded-xl border px-3"/><select value={serviceType} onChange={e=>setServiceType(e.target.value)} className="h-11 rounded-xl border px-3">{services.map(x=><option key={x}>{x}</option>)}</select><select value={pickup} onChange={e=>setPickup(e.target.value)} className="h-11 rounded-xl border px-3"><option value="">Pickup not configured</option>{parents.map(x=><option key={x._id} value={x._id}>{x.name}</option>)}</select><Button disabled={saving||!name.trim()} onClick={()=>void create()}>Create vendor</Button></div></section><div className="grid gap-6 lg:grid-cols-[.9fr_1.1fr]"><section className="space-y-3">{vendors.map(v=><button key={v._id} onClick={()=>void loadCoverage(v)} className="w-full rounded-2xl border bg-white p-4 text-left"><div className="flex justify-between gap-3"><div><b>{v.name}</b><p className="text-sm text-slate-500">{v.serviceType} · Pickup: {v.pickupParent?.name||'Not configured'}</p></div><span className={v.readiness==='ready'?'text-emerald-700':v.readiness==='inactive'?'text-slate-500':'text-amber-700'}>{v.readiness==='ready'?'Ready':v.readiness==='inactive'?'Inactive':'Needs setup'}</span></div><p className="mt-2 text-xs text-slate-500">{v.coverageCount} enabled destinations</p></button>)}</section><section className="rounded-2xl border bg-white p-5">{selected?<><div className="flex justify-between gap-3"><div><h2 className="font-bold">Delivery coverage · {selected.name}</h2><p className="mt-1 text-sm text-slate-500">Enable only locations this vendor serves.</p></div><Button size="sm" variant={selected.active?'outline':'default'} disabled={saving} onClick={()=>void setActive(!selected.active)}>{selected.active?'Deactivate':'Activate'}</Button></div><div className="mt-4 rounded-xl bg-slate-50 p-3"><label className="text-sm font-semibold">Pickup parent location</label><div className="mt-2 flex gap-2"><select value={editPickup} onChange={e=>setEditPickup(e.target.value)} className="h-10 min-w-0 flex-1 rounded-lg border px-3"><option value="">Not configured</option>{parents.map(p=><option key={p._id} value={p._id}>{p.name}</option>)}</select><Button size="sm" variant="outline" disabled={saving} onClick={()=>void savePickup()}>Save pickup</Button></div></div><div className="mt-4 flex flex-wrap gap-2"><input value={duplicateName} onChange={e=>setDuplicateName(e.target.value)} placeholder="Name for duplicate" className="h-10 min-w-48 flex-1 rounded-lg border px-3"/><select value={duplicateServiceType} onChange={e=>setDuplicateServiceType(e.target.value)} className="h-10 rounded-lg border px-3">{services.map(x=><option key={x} value={x}>{x}</option>)}</select><Button variant="outline" disabled={saving||!duplicateName.trim()} onClick={()=>void duplicate()}>Duplicate</Button></div><div className="mt-4 space-y-2">{destinations.map(d=><div key={d.parentLocationId} className="grid grid-cols-[1fr_auto_110px_auto] items-center gap-3 rounded-xl bg-slate-50 p-3"><span className="font-medium">{d.name}</span><input type="checkbox" checked={d.enabled} onChange={e=>setDestinations(xs=>xs.map(x=>x.parentLocationId===d.parentLocationId?{...x,enabled:e.target.checked}:x))}/><input inputMode="numeric" value={d.serviceFee||''} onChange={e=>setDestinations(xs=>xs.map(x=>x.parentLocationId===d.parentLocationId?{...x,serviceFee:Number(e.target.value)||null}:x))} placeholder="Fee" className="h-9 rounded-lg border px-2"/><Button size="sm" variant="outline" onClick={()=>void saveRule(d)}>Save</Button></div>)}</div></>:<p className="text-sm text-slate-500">Select a vendor to configure coverage and pricing.</p>}</section></div></main>
}
